INSERT IGNORE INTO graha_rashi (graha_id, rashi_id, interpretation_np, interpretation_en, positive_effects, challenges, career_indication, financial_indication, relationship_indication, classical_interpretation, sanskrit_reference, remedies) VALUES
(1,2,'सूर्य मित्र राशिमा सहज र शुभ फल दिन्छ। वृषभ राशिको स्थिर र व्यावहारिक स्वभाव र सूर्यको नेतृत्व शक्ति मिसिएर जीवनमा सहजता र वृद्धि हुने। यसले संचय र स्थिरतामा विशेष प्रभाव देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व, प्रतिष्ठा, सरकारी सम्मान, धैर्य','अहंकार, क्रोध, जल्दबाजी, जिद','प्रशासन, राज्यसेवा, नेतृत्व, कृषि','सरकारी स्रोतबाट लाभ, स्थिर आय, बचत र भूमि लाभ','आफ्नो कुरा मान्ने जिद, तर सम्मान, वफादार र शान्त','सूर्यो वृषभे मित्रस्थो हितकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,3,'सूर्य मित्र राशिमा सहज र शुभ फल दिन्छ। मिथुन राशिको चञ्चल र सञ्चारी स्वभाव र सूर्यको नेतृत्व शक्ति मिसिएर जीवनमा सहजता र वृद्धि हुने। यसले वाणी र सम्बन्धमा विशेष प्रभाव देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व, प्रतिष्ठा, सरकारी सम्मान, वाणी','अहंकार, क्रोध, जल्दबाजी, द्विधा','प्रशासन, राज्यसेवा, नेतृत्व, लेखन','सरकारी स्रोतबाट लाभ, स्थिर आय, बहुआय','आफ्नो कुरा मान्ने जिद, तर सम्मान, मैत्रीपूर्ण तर भावना चञ्चल','सूर्यो मिथुने मित्रस्थो हितकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,4,'सूर्य सामान्य अवस्थामा मध्यम फल दिन्छ। कर्क राशिको भावनात्मक र पोषक स्वभाव र सूर्यको नेतृत्व शक्ति मिसिएर फल मध्यम र सन्तुलित रहने। यसले परिवार र सुरक्षामा विशेष प्रभाव देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व, प्रतिष्ठा, सरकारी सम्मान, करुणा','अहंकार, क्रोध, जल्दबाजी, मनोद्वन्द्व','प्रशासन, राज्यसेवा, नेतृत्व, खाद्य','सरकारी स्रोतबाट लाभ, स्थिर आय, चल सम्पत्ति','आफ्नो कुरा मान्ने जिद, तर सम्मान, गहिरो स्नेह र ममता','सूर्यो कर्के सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,6,'सूर्य शत्रु राशिमा अवरोध र कष्ट दिन्छ। कन्या राशिको विश्लेषक र सेवाभावी स्वभाव र सूर्यको नेतृत्व शक्ति मिसिएर चुनौती र अवरोध आउँदै अनुभव हुने। यसले सेवा र व्यवस्थापनमा विशेष प्रभाव देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व, प्रतिष्ठा, सरकारी सम्मान, विश्लेषण','अहंकार, क्रोध, जल्दबाजी, आलोचनात्मकता','प्रशासन, राज्यसेवा, नेतृत्व, चिकित्सा','सरकारी स्रोतबाट लाभ, स्थिर आय, योजनाबद्ध बचत','आफ्नो कुरा मान्ने जिद, तर सम्मान, व्यावहारिक स्नेह','सूर्यो कन्यायां शत्रुस्थो दुःखकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,7,'सूर्य नीच अवस्थामा कमजोर भई फलमा बाधा ल्याउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभाव र सूर्यको नेतृत्व शक्ति मिसिएर फल कमजोर र बाधापूर्ण बन्ने। यसले न्याय र सामञ्जस्यमा विशेष प्रभाव देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व, प्रतिष्ठा, सरकारी सम्मान, न्याय','अहंकार, क्रोध, जल्दबाजी, निर्णय ढिलाइ','प्रशासन, राज्यसेवा, नेतृत्व, कानुन','सरकारी स्रोतबाट लाभ, स्थिर आय, सन्तुलित आय','आफ्नो कुरा मान्ने जिद, तर सम्मान, सामञ्जस्यपूर्ण जीवनसाथी','सूर्यो तुलायां नीचस्थो दुर्बलः भवति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,8,'सूर्य सामान्य अवस्थामा मध्यम फल दिन्छ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभाव र सूर्यको नेतृत्व शक्ति मिसिएर फल मध्यम र सन्तुलित रहने। यसले अन्तर्दृष्टि र परिवर्तनमा विशेष प्रभाव देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व, प्रतिष्ठा, सरकारी सम्मान, अन्तर्दृष्टि','अहंकार, क्रोध, जल्दबाजी, षड्यन्त्रवाद','प्रशासन, राज्यसेवा, नेतृत्व, अनुसन्धान','सरकारी स्रोतबाट लाभ, स्थिर आय, अचानक उतारचढाव','आफ्नो कुरा मान्ने जिद, तर सम्मान, गहिरो तर तीव्र','सूर्यो वृश्चिके सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,9,'सूर्य सामान्य अवस्थामा मध्यम फल दिन्छ। धनु राशिको धार्मिक र जिज्ञासु स्वभाव र सूर्यको नेतृत्व शक्ति मिसिएर फल मध्यम र सन्तुलित रहने। यसले ज्ञान र यात्रामा विशेष प्रभाव देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व, प्रतिष्ठा, सरकारी सम्मान, ज्ञान','अहंकार, क्रोध, जल्दबाजी, अति विश्वास','प्रशासन, राज्यसेवा, नेतृत्व, शिक्षण','सरकारी स्रोतबाट लाभ, स्थिर आय, भाग्यबाट लाभ','आफ्नो कुरा मान्ने जिद, तर सम्मान, स्वतन्त्रता दिने','सूर्यो धनौ सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,'सूर्य सामान्य अवस्थामा मध्यम फल दिन्छ। मकर राशिको अनुशासित र धैर्यवान स्वभाव र सूर्यको नेतृत्व शक्ति मिसिएर फल मध्यम र सन्तुलित रहने। यसले कर्म र उन्नतिमा विशेष प्रभाव देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व, प्रतिष्ठा, सरकारी सम्मान, कर्मठता','अहंकार, क्रोध, जल्दबाजी, निराशावाद','प्रशासन, राज्यसेवा, नेतृत्व, व्यवस्थापन','सरकारी स्रोतबाट लाभ, स्थिर आय, हौले हौले सम्पत्ति','आफ्नो कुरा मान्ने जिद, तर सम्मान, जिम्मेवार तर शब्द कम','सूर्यो मकरे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,11,'सूर्य सामान्य अवस्थामा मध्यम फल दिन्छ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभाव र सूर्यको नेतृत्व शक्ति मिसिएर फल मध्यम र सन्तुलित रहने। यसले नवप्रवर्तन र मित्रतामा विशेष प्रभाव देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व, प्रतिष्ठा, सरकारी सम्मान, नवप्रवर्तन','अहंकार, क्रोध, जल्दबाजी, विद्रोहीपन','प्रशासन, राज्यसेवा, नेतृत्व, प्रविधि','सरकारी स्रोतबाट लाभ, स्थिर आय, नवीन तर अनियमित स्रोत','आफ्नो कुरा मान्ने जिद, तर सम्मान, मित्रतामा आधारित','सूर्यो कुम्भे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,12,'सूर्य सामान्य अवस्थामा मध्यम फल दिन्छ। मीन राशिको करुणामय र आध्यात्मिक स्वभाव र सूर्यको नेतृत्व शक्ति मिसिएर फल मध्यम र सन्तुलित रहने। यसले करुणा र कल्पनामा विशेष प्रभाव देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व, प्रतिष्ठा, सरकारी सम्मान, कल्पनाशक्ति','अहंकार, क्रोध, जल्दबाजी, अस्पष्टता','प्रशासन, राज्यसेवा, नेतृत्व, कला','सरकारी स्रोतबाट लाभ, स्थिर आय, स्रोत अनिश्चित','आफ्नो कुरा मान्ने जिद, तर सम्मान, निःशर्त प्रेम','सूर्यो मीने सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(2,1,'चन्द्र मित्र राशिमा सहज र शुभ फल दिन्छ। मेष राशिको साहसी र ऊर्जावान स्वभाव र चन्द्रको भावनात्मक प्रभाव मिसिएर जीवनमा सहजता र वृद्धि हुने। यसले नेतृत्व र पहलकदमीमा विशेष प्रभाव देखिन्छ।',NULL,'लोकप्रियता, करुणा, स्मृति शक्ति, साहस, नेतृत्व','मनोद्वन्द्व, भावनात्मक अस्थिरता, जल्दबाजी, क्रोध','जनसेवा, शिक्षा, खाद्य व्यवसाय, सेना','चल सम्पत्ति, जलजन्य आय, आत्मप्रयासबाट आय','गहिरो स्नेह, भावनामा उतारचढाव, ऊर्जावान तर धैर्य कम','चन्द्रो मेषे मित्रस्थो हितकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,2,'चन्द्र वृषभ राशिमा उच्चस्थ भई चरम बल पाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभाव र चन्द्रको भावनात्मक प्रभाव मिसिएर संयोजन उत्कृष्ट र उज्ज्वल फल दिने। यसले संचय र स्थिरतामा विशेष प्रभाव देखिन्छ।',NULL,'लोकप्रियता, करुणा, स्मृति शक्ति, धैर्य, संचय','मनोद्वन्द्व, भावनात्मक अस्थिरता, जिद, अति संग्रह','जनसेवा, शिक्षा, खाद्य व्यवसाय, कृषि','चल सम्पत्ति, जलजन्य आय, बचत र भूमि लाभ','गहिरो स्नेह, भावनामा उतारचढाव, वफादार र शान्त','चन्द्रो वृषभे उच्चस्थो बलवान् भवति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,3,'चन्द्र सामान्य अवस्थामा मध्यम फल दिन्छ। मिथुन राशिको चञ्चल र सञ्चारी स्वभाव र चन्द्रको भावनात्मक प्रभाव मिसिएर फल मध्यम र सन्तुलित रहने। यसले वाणी र सम्बन्धमा विशेष प्रभाव देखिन्छ।',NULL,'लोकप्रियता, करुणा, स्मृति शक्ति, वाणी, बुद्धि','मनोद्वन्द्व, भावनात्मक अस्थिरता, द्विधा, अस्थिरता','जनसेवा, शिक्षा, खाद्य व्यवसाय, लेखन','चल सम्पत्ति, जलजन्य आय, बहुआय','गहिरो स्नेह, भावनामा उतारचढाव, मैत्रीपूर्ण तर भावना चञ्चल','चन्द्रो मिथुने सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,5,'चन्द्र सामान्य अवस्थामा मध्यम फल दिन्छ। सिंह राशिको राजसी र आत्मविश्वासी स्वभाव र चन्द्रको भावनात्मक प्रभाव मिसिएर फल मध्यम र सन्तुलित रहने। यसले प्रतिष्ठा र नेतृत्वमा विशेष प्रभाव देखिन्छ।',NULL,'लोकप्रियता, करुणा, स्मृति शक्ति, नेतृत्व, दानशीलता','मनोद्वन्द्व, भावनात्मक अस्थिरता, अहंकार, दम्भ','जनसेवा, शिक्षा, खाद्य व्यवसाय, प्रशासन','चल सम्पत्ति, जलजन्य आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','गहिरो स्नेह, भावनामा उतारचढाव, आदर चाहने','चन्द्रो सिंहे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,6,'चन्द्र सामान्य अवस्थामा मध्यम फल दिन्छ। कन्या राशिको विश्लेषक र सेवाभावी स्वभाव र चन्द्रको भावनात्मक प्रभाव मिसिएर फल मध्यम र सन्तुलित रहने। यसले सेवा र व्यवस्थापनमा विशेष प्रभाव देखिन्छ।',NULL,'लोकप्रियता, करुणा, स्मृति शक्ति, विश्लेषण, शुद्धता','मनोद्वन्द्व, भावनात्मक अस्थिरता, आलोचनात्मकता, चिन्ता','जनसेवा, शिक्षा, खाद्य व्यवसाय, चिकित्सा','चल सम्पत्ति, जलजन्य आय, योजनाबद्ध बचत','गहिरो स्नेह, भावनामा उतारचढाव, व्यावहारिक स्नेह','चन्द्रो कन्यायां सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,7,'चन्द्र सामान्य अवस्थामा मध्यम फल दिन्छ। तुला राशिको सन्तुलित र कलात्मक स्वभाव र चन्द्रको भावनात्मक प्रभाव मिसिएर फल मध्यम र सन्तुलित रहने। यसले न्याय र सामञ्जस्यमा विशेष प्रभाव देखिन्छ।',NULL,'लोकप्रियता, करुणा, स्मृति शक्ति, न्याय, सौन्दर्य','मनोद्वन्द्व, भावनात्मक अस्थिरता, निर्णय ढिलाइ, अति सम्झौता','जनसेवा, शिक्षा, खाद्य व्यवसाय, कानुन','चल सम्पत्ति, जलजन्य आय, सन्तुलित आय','गहिरो स्नेह, भावनामा उतारचढाव, सामञ्जस्यपूर्ण जीवनसाथी','चन्द्रो तुलायां सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,8,'चन्द्र नीच अवस्थामा कमजोर भई फलमा बाधा ल्याउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभाव र चन्द्रको भावनात्मक प्रभाव मिसिएर फल कमजोर र बाधापूर्ण बन्ने। यसले अन्तर्दृष्टि र परिवर्तनमा विशेष प्रभाव देखिन्छ।',NULL,'लोकप्रियता, करुणा, स्मृति शक्ति, अन्तर्दृष्टि, परिवर्तन','मनोद्वन्द्व, भावनात्मक अस्थिरता, षड्यन्त्रवाद, अति गोपन','जनसेवा, शिक्षा, खाद्य व्यवसाय, अनुसन्धान','चल सम्पत्ति, जलजन्य आय, अचानक उतारचढाव','गहिरो स्नेह, भावनामा उतारचढाव, गहिरो तर तीव्र','चन्द्रो वृश्चिके नीचस्थो दुर्बलः भवति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,9,'चन्द्र सामान्य अवस्थामा मध्यम फल दिन्छ। धनु राशिको धार्मिक र जिज्ञासु स्वभाव र चन्द्रको भावनात्मक प्रभाव मिसिएर फल मध्यम र सन्तुलित रहने। यसले ज्ञान र यात्रामा विशेष प्रभाव देखिन्छ।',NULL,'लोकप्रियता, करुणा, स्मृति शक्ति, ज्ञान, आशावाद','मनोद्वन्द्व, भावनात्मक अस्थिरता, अति विश्वास, उद्देश्य भ्रम','जनसेवा, शिक्षा, खाद्य व्यवसाय, शिक्षण','चल सम्पत्ति, जलजन्य आय, भाग्यबाट लाभ','गहिरो स्नेह, भावनामा उतारचढाव, स्वतन्त्रता दिने','चन्द्रो धनौ सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,10,'चन्द्र सामान्य अवस्थामा मध्यम फल दिन्छ। मकर राशिको अनुशासित र धैर्यवान स्वभाव र चन्द्रको भावनात्मक प्रभाव मिसिएर फल मध्यम र सन्तुलित रहने। यसले कर्म र उन्नतिमा विशेष प्रभाव देखिन्छ।',NULL,'लोकप्रियता, करुणा, स्मृति शक्ति, कर्मठता, धैर्य','मनोद्वन्द्व, भावनात्मक अस्थिरता, निराशावाद, कठोरता','जनसेवा, शिक्षा, खाद्य व्यवसाय, प्रशासन','चल सम्पत्ति, जलजन्य आय, हौले हौले सम्पत्ति','गहिरो स्नेह, भावनामा उतारचढाव, जिम्मेवार तर शब्द कम','चन्द्रो मकरे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,11,'चन्द्र सामान्य अवस्थामा मध्यम फल दिन्छ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभाव र चन्द्रको भावनात्मक प्रभाव मिसिएर फल मध्यम र सन्तुलित रहने। यसले नवप्रवर्तन र मित्रतामा विशेष प्रभाव देखिन्छ।',NULL,'लोकप्रियता, करुणा, स्मृति शक्ति, नवप्रवर्तन, मित्रता','मनोद्वन्द्व, भावनात्मक अस्थिरता, विद्रोहीपन, भावनात्मक टाढा','जनसेवा, शिक्षा, खाद्य व्यवसाय, प्रविधि','चल सम्पत्ति, जलजन्य आय, नवीन तर अनियमित स्रोत','गहिरो स्नेह, भावनामा उतारचढाव, मित्रतामा आधारित','चन्द्रो कुम्भे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,12,'चन्द्र सामान्य अवस्थामा मध्यम फल दिन्छ। मीन राशिको करुणामय र आध्यात्मिक स्वभाव र चन्द्रको भावनात्मक प्रभाव मिसिएर फल मध्यम र सन्तुलित रहने। यसले करुणा र कल्पनामा विशेष प्रभाव देखिन्छ।',NULL,'लोकप्रियता, करुणा, स्मृति शक्ति, कल्पनाशक्ति, आध्यात्मिकता','मनोद्वन्द्व, भावनात्मक अस्थिरता, अस्पष्टता, भाग्यमा अति निर्भरता','जनसेवा, शिक्षा, खाद्य व्यवसाय, कला','चल सम्पत्ति, जलजन्य आय, स्रोत अनिश्चित','गहिरो स्नेह, भावनामा उतारचढाव, निःशर्त प्रेम','चन्द्रो मीने सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(3,2,'मङ्गल मित्र राशिमा सहज र शुभ फल दिन्छ। वृषभ राशिको स्थिर र व्यावहारिक स्वभाव र मङ्गलको पराक्रम मिसिएर जीवनमा सहजता र वृद्धि हुने। यसले संचय र स्थिरतामा विशेष प्रभाव देखिन्छ।',NULL,'साहस, पराक्रम, विजय, धैर्य, संचय','क्रोध, विवाद, दुर्घटना, जिद','सेना, खेलकुद, इन्जिनियरिङ, कृषि','भूमि र पराक्रमबाट लाभ, बचत र भूमि लाभ','तीव्र भावना, विवाद, वफादार र शान्त','मङ्गलो वृषभे मित्रस्थो हितकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 6','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,3,'मङ्गल सामान्य अवस्थामा मध्यम फल दिन्छ। मिथुन राशिको चञ्चल र सञ्चारी स्वभाव र मङ्गलको पराक्रम मिसिएर फल मध्यम र सन्तुलित रहने। यसले वाणी र सम्बन्धमा विशेष प्रभाव देखिन्छ।',NULL,'साहस, पराक्रम, विजय, वाणी, बुद्धि','क्रोध, विवाद, दुर्घटना, द्विधा','सेना, खेलकुद, इन्जिनियरिङ, लेखन','भूमि र पराक्रमबाट लाभ, बहुआय, अनियमित','तीव्र भावना, विवाद, मैत्रीपूर्ण तर भावना चञ्चल','मङ्गलो मिथुने सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 6','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,4,'मङ्गल नीच अवस्थामा कमजोर भई फलमा बाधा ल्याउँछ। कर्क राशिको भावनात्मक र पोषक स्वभाव र मङ्गलको पराक्रम मिसिएर फल कमजोर र बाधापूर्ण बन्ने। यसले परिवार र सुरक्षामा विशेष प्रभाव देखिन्छ।',NULL,'साहस, पराक्रम, विजय, करुणा, स्मृति','क्रोध, विवाद, दुर्घटना, मनोद्वन्द्व','सेना, खेलकुद, इन्जिनियरिङ, खाद्य','भूमि र पराक्रमबाट लाभ, चल सम्पत्ति, जलजन्य आय','तीव्र भावना, विवाद, गहिरो स्नेह र ममता','मङ्गलो कर्के नीचस्थो दुर्बलः भवति।','Brihat Parashara Hora Shastra, Adhyaya 6','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,5,'मङ्गल मित्र राशिमा सहज र शुभ फल दिन्छ। सिंह राशिको राजसी र आत्मविश्वासी स्वभाव र मङ्गलको पराक्रम मिसिएर जीवनमा सहजता र वृद्धि हुने। यसले प्रतिष्ठा र नेतृत्वमा विशेष प्रभाव देखिन्छ।',NULL,'साहस, पराक्रम, विजय, नेतृत्व, दानशीलता','क्रोध, विवाद, दुर्घटना, अहंकार','सेना, खेलकुद, इन्जिनियरिङ, प्रशासन','भूमि र पराक्रमबाट लाभ, उदार खर्चसँगै प्रतिष्ठाजनक आय','तीव्र भावना, विवाद, आदर चाहने','मङ्गलो सिंहे मित्रस्थो हितकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 6','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,6,'मङ्गल शत्रु राशिमा अवरोध र कष्ट दिन्छ। कन्या राशिको विश्लेषक र सेवाभावी स्वभाव र मङ्गलको पराक्रम मिसिएर चुनौती र अवरोध आउँदै अनुभव हुने। यसले सेवा र व्यवस्थापनमा विशेष प्रभाव देखिन्छ।',NULL,'साहस, पराक्रम, विजय, विश्लेषण, शुद्धता','क्रोध, विवाद, दुर्घटना, आलोचनात्मकता','सेना, खेलकुद, इन्जिनियरिङ, चिकित्सा','भूमि र पराक्रमबाट लाभ, योजनाबद्ध बचत','तीव्र भावना, विवाद, व्यावहारिक स्नेह','मङ्गलो कन्यायां शत्रुस्थो दुःखकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 6','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,7,'मङ्गल सामान्य अवस्थामा मध्यम फल दिन्छ। तुला राशिको सन्तुलित र कलात्मक स्वभाव र मङ्गलको पराक्रम मिसिएर फल मध्यम र सन्तुलित रहने। यसले न्याय र सामञ्जस्यमा विशेष प्रभाव देखिन्छ।',NULL,'साहस, पराक्रम, विजय, न्याय, सौन्दर्य','क्रोध, विवाद, दुर्घटना, निर्णय ढिलाइ','सेना, खेलकुद, इन्जिनियरिङ, कानुन','भूमि र पराक्रमबाट लाभ, सन्तुलित आय','तीव्र भावना, विवाद, सामञ्जस्यपूर्ण जीवनसाथी','मङ्गलो तुलायां सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 6','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,9,'मङ्गल सामान्य अवस्थामा मध्यम फल दिन्छ। धनु राशिको धार्मिक र जिज्ञासु स्वभाव र मङ्गलको पराक्रम मिसिएर फल मध्यम र सन्तुलित रहने। यसले ज्ञान र यात्रामा विशेष प्रभाव देखिन्छ।',NULL,'साहस, पराक्रम, विजय, ज्ञान, आशावाद','क्रोध, विवाद, दुर्घटना, अति विश्वास','सेना, खेलकुद, इन्जिनियरिङ, शिक्षण','भूमि र पराक्रमबाट लाभ, भाग्यबाट लाभ, उदार खर्च','तीव्र भावना, विवाद, स्वतन्त्रता दिने','मङ्गलो धनौ सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 6','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,10,'मङ्गल मकर राशिमा उच्चस्थ भई चरम बल पाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभाव र मङ्गलको पराक्रम मिसिएर संयोजन उत्कृष्ट र उज्ज्वल फल दिने। यसले कर्म र उन्नतिमा विशेष प्रभाव देखिन्छ।',NULL,'साहस, पराक्रम, विजय, कर्मठता, धैर्य','क्रोध, विवाद, दुर्घटना, निराशावाद','सेना, खेलकुद, इन्जिनियरिङ, प्रशासन','भूमि र पराक्रमबाट लाभ, हौले हौले सम्पत्ति','तीव्र भावना, विवाद, जिम्मेवार तर शब्द कम','मङ्गलो मकरे उच्चस्थो बलवान् भवति।','Brihat Parashara Hora Shastra, Adhyaya 6','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,11,'मङ्गल सामान्य अवस्थामा मध्यम फल दिन्छ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभाव र मङ्गलको पराक्रम मिसिएर फल मध्यम र सन्तुलित रहने। यसले नवप्रवर्तन र मित्रतामा विशेष प्रभाव देखिन्छ।',NULL,'साहस, पराक्रम, विजय, नवप्रवर्तन, मित्रता','क्रोध, विवाद, दुर्घटना, विद्रोहीपन','सेना, खेलकुद, इन्जिनियरिङ, प्रविधि','भूमि र पराक्रमबाट लाभ, नवीन तर अनियमित स्रोत','तीव्र भावना, विवाद, मित्रतामा आधारित','मङ्गलो कुम्भे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 6','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,12,'मङ्गल सामान्य अवस्थामा मध्यम फल दिन्छ। मीन राशिको करुणामय र आध्यात्मिक स्वभाव र मङ्गलको पराक्रम मिसिएर फल मध्यम र सन्तुलित रहने। यसले करुणा र कल्पनामा विशेष प्रभाव देखिन्छ।',NULL,'साहस, पराक्रम, विजय, कल्पनाशक्ति, करुणा','क्रोध, विवाद, दुर्घटना, अस्पष्टता','सेना, खेलकुद, इन्जिनियरिङ, कला','भूमि र पराक्रमबाट लाभ, स्रोत अनिश्चित, दानशीलता','तीव्र भावना, विवाद, निःशर्त प्रेम','मङ्गलो मीने सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 6','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(4,1,'बुध मित्र राशिमा सहज र शुभ फल दिन्छ। मेष राशिको साहसी र ऊर्जावान स्वभाव र बुधको बौद्धिक क्षमता मिसिएर जीवनमा सहजता र वृद्धि हुने। यसले नेतृत्व र पहलकदमीमा विशेष प्रभाव देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक समझ, साहस, नेतृत्व','द्विधा, अति बोली, जल्दबाजी, क्रोध','लेखन, व्यापार, सञ्चार, सेना','व्यापारबाट लाभ, बहुआय, आत्मप्रयासबाट आय','संवादमा दक्ष, तर भावना कम, ऊर्जावान तर धैर्य कम','बुधो मेषे मित्रस्थो हितकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,2,'बुध शत्रु राशिमा अवरोध र कष्ट दिन्छ। वृषभ राशिको स्थिर र व्यावहारिक स्वभाव र बुधको बौद्धिक क्षमता मिसिएर चुनौती र अवरोध आउँदै अनुभव हुने। यसले संचय र स्थिरतामा विशेष प्रभाव देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक समझ, धैर्य, संचय','द्विधा, अति बोली, जिद, अति संग्रह','लेखन, व्यापार, सञ्चार, कृषि','व्यापारबाट लाभ, बहुआय, बचत र भूमि लाभ','संवादमा दक्ष, तर भावना कम, वफादार र शान्त','बुधो वृषभे शत्रुस्थो दुःखकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,4,'बुध सामान्य अवस्थामा मध्यम फल दिन्छ। कर्क राशिको भावनात्मक र पोषक स्वभाव र बुधको बौद्धिक क्षमता मिसिएर फल मध्यम र सन्तुलित रहने। यसले परिवार र सुरक्षामा विशेष प्रभाव देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक समझ, करुणा, स्मृति','द्विधा, अति बोली, मनोद्वन्द्व, कुढ्ने स्वभाव','लेखन, व्यापार, सञ्चार, खाद्य','व्यापारबाट लाभ, बहुआय, चल सम्पत्ति','संवादमा दक्ष, तर भावना कम, गहिरो स्नेह र ममता','बुधो कर्के सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,5,'बुध सामान्य अवस्थामा मध्यम फल दिन्छ। सिंह राशिको राजसी र आत्मविश्वासी स्वभाव र बुधको बौद्धिक क्षमता मिसिएर फल मध्यम र सन्तुलित रहने। यसले प्रतिष्ठा र नेतृत्वमा विशेष प्रभाव देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक समझ, नेतृत्व, दानशीलता','द्विधा, अति बोली, अहंकार, दम्भ','लेखन, व्यापार, सञ्चार, प्रशासन','व्यापारबाट लाभ, बहुआय, उदार खर्चसँगै प्रतिष्ठाजनक आय','संवादमा दक्ष, तर भावना कम, आदर चाहने','बुधो सिंहे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,6,'बुध कन्या राशिमा उच्चस्थ भई चरम बल पाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभाव र बुधको बौद्धिक क्षमता मिसिएर संयोजन उत्कृष्ट र उज्ज्वल फल दिने। यसले सेवा र व्यवस्थापनमा विशेष प्रभाव देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक समझ, विश्लेषण, शुद्धता','द्विधा, अति बोली, आलोचनात्मकता, चिन्ता','लेखन, व्यापार, सञ्चार, चिकित्सा','व्यापारबाट लाभ, बहुआय, योजनाबद्ध बचत','संवादमा दक्ष, तर भावना कम, व्यावहारिक स्नेह','बुधो कन्यायां उच्चस्थो बलवान् भवति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,7,'बुध सामान्य अवस्थामा मध्यम फल दिन्छ। तुला राशिको सन्तुलित र कलात्मक स्वभाव र बुधको बौद्धिक क्षमता मिसिएर फल मध्यम र सन्तुलित रहने। यसले न्याय र सामञ्जस्यमा विशेष प्रभाव देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक समझ, न्याय, सौन्दर्य','द्विधा, अति बोली, निर्णय ढिलाइ, अति सम्झौता','लेखन, व्यापार, सञ्चार, कानुन','व्यापारबाट लाभ, बहुआय, सन्तुलित आय','संवादमा दक्ष, तर भावना कम, सामञ्जस्यपूर्ण जीवनसाथी','बुधो तुलायां सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,8,'बुध सामान्य अवस्थामा मध्यम फल दिन्छ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभाव र बुधको बौद्धिक क्षमता मिसिएर फल मध्यम र सन्तुलित रहने। यसले अन्तर्दृष्टि र परिवर्तनमा विशेष प्रभाव देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक समझ, अन्तर्दृष्टि, परिवर्तन','द्विधा, अति बोली, षड्यन्त्रवाद, अति गोपन','लेखन, व्यापार, सञ्चार, अनुसन्धान','व्यापारबाट लाभ, बहुआय, अचानक उतारचढाव','संवादमा दक्ष, तर भावना कम, गहिरो तर तीव्र','बुधो वृश्चिके सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,9,'बुध सामान्य अवस्थामा मध्यम फल दिन्छ। धनु राशिको धार्मिक र जिज्ञासु स्वभाव र बुधको बौद्धिक क्षमता मिसिएर फल मध्यम र सन्तुलित रहने। यसले ज्ञान र यात्रामा विशेष प्रभाव देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक समझ, ज्ञान, आशावाद','द्विधा, अति बोली, अति विश्वास, उद्देश्य भ्रम','लेखन, व्यापार, सञ्चार, शिक्षण','व्यापारबाट लाभ, बहुआय, भाग्यबाट लाभ','संवादमा दक्ष, तर भावना कम, स्वतन्त्रता दिने','बुधो धनौ सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,10,'बुध सामान्य अवस्थामा मध्यम फल दिन्छ। मकर राशिको अनुशासित र धैर्यवान स्वभाव र बुधको बौद्धिक क्षमता मिसिएर फल मध्यम र सन्तुलित रहने। यसले कर्म र उन्नतिमा विशेष प्रभाव देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक समझ, कर्मठता, धैर्य','द्विधा, अति बोली, निराशावाद, कठोरता','लेखन, व्यापार, सञ्चार, प्रशासन','व्यापारबाट लाभ, बहुआय, हौले हौले सम्पत्ति','संवादमा दक्ष, तर भावना कम, जिम्मेवार तर शब्द कम','बुधो मकरे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,11,'बुध सामान्य अवस्थामा मध्यम फल दिन्छ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभाव र बुधको बौद्धिक क्षमता मिसिएर फल मध्यम र सन्तुलित रहने। यसले नवप्रवर्तन र मित्रतामा विशेष प्रभाव देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक समझ, नवप्रवर्तन, मित्रता','द्विधा, अति बोली, विद्रोहीपन, भावनात्मक टाढा','लेखन, व्यापार, सञ्चार, प्रविधि','व्यापारबाट लाभ, बहुआय, नवीन तर अनियमित स्रोत','संवादमा दक्ष, तर भावना कम, मित्रतामा आधारित','बुधो कुम्भे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,12,'बुध नीच अवस्थामा कमजोर भई फलमा बाधा ल्याउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभाव र बुधको बौद्धिक क्षमता मिसिएर फल कमजोर र बाधापूर्ण बन्ने। यसले करुणा र कल्पनामा विशेष प्रभाव देखिन्छ।',NULL,'बुद्धिमत्ता, वाणी कला, व्यापारिक समझ, कल्पनाशक्ति, करुणा','द्विधा, अति बोली, अस्पष्टता, भाग्यमा अति निर्भरता','लेखन, व्यापार, सञ्चार, कला','व्यापारबाट लाभ, बहुआय, स्रोत अनिश्चित','संवादमा दक्ष, तर भावना कम, निःशर्त प्रेम','बुधो मीने नीचस्थो दुर्बलः भवति।','Brihat Parashara Hora Shastra, Adhyaya 10','बुधवार गणेशलाई दूर्वा चढाउने।'),
(5,1,'गुरु मित्र राशिमा सहज र शुभ फल दिन्छ। मेष राशिको साहसी र ऊर्जावान स्वभाव र गुरुको ज्ञान गुण मिसिएर जीवनमा सहजता र वृद्धि हुने। यसले नेतृत्व र पहलकदमीमा विशेष प्रभाव देखिन्छ।',NULL,'ज्ञान, भाग्य, धर्म, दीर्घायु, साहस','अति उदारता, अति आशावाद, जल्दबाजी, क्रोध','शिक्षण, धर्म, विधि, सेना','भाग्यबाट लाभ, आत्मप्रयासबाट आय','ज्ञानी सल्लाहकार, उदार, ऊर्जावान तर धैर्य कम','गुरुः मेषे मित्रस्थो हितकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 11','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,2,'गुरु मित्र राशिमा सहज र शुभ फल दिन्छ। वृषभ राशिको स्थिर र व्यावहारिक स्वभाव र गुरुको ज्ञान गुण मिसिएर जीवनमा सहजता र वृद्धि हुने। यसले संचय र स्थिरतामा विशेष प्रभाव देखिन्छ।',NULL,'ज्ञान, भाग्य, धर्म, दीर्घायु, धैर्य','अति उदारता, अति आशावाद, जिद, अति संग्रह','शिक्षण, धर्म, विधि, कृषि','भाग्यबाट लाभ, बचत र भूमि लाभ','ज्ञानी सल्लाहकार, उदार, वफादार र शान्त','गुरुः वृषभे मित्रस्थो हितकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 11','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,3,'गुरु मित्र राशिमा सहज र शुभ फल दिन्छ। मिथुन राशिको चञ्चल र सञ्चारी स्वभाव र गुरुको ज्ञान गुण मिसिएर जीवनमा सहजता र वृद्धि हुने। यसले वाणी र सम्बन्धमा विशेष प्रभाव देखिन्छ।',NULL,'ज्ञान, भाग्य, धर्म, दीर्घायु, वाणी','अति उदारता, अति आशावाद, द्विधा, अस्थिरता','शिक्षण, धर्म, विधि, लेखन','भाग्यबाट लाभ, बहुआय, अनियमित','ज्ञानी सल्लाहकार, उदार, मैत्रीपूर्ण तर भावना चञ्चल','गुरुः मिथुने मित्रस्थो हितकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 11','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,4,'गुरु शत्रु राशिमा अवरोध र कष्ट दिन्छ। कर्क राशिको भावनात्मक र पोषक स्वभाव र गुरुको ज्ञान गुण मिसिएर चुनौती र अवरोध आउँदै अनुभव हुने। यसले परिवार र सुरक्षामा विशेष प्रभाव देखिन्छ।',NULL,'ज्ञान, भाग्य, धर्म, दीर्घायु, करुणा','अति उदारता, अति आशावाद, मनोद्वन्द्व, कुढ्ने स्वभाव','शिक्षण, धर्म, विधि, खाद्य','भाग्यबाट लाभ, चल सम्पत्ति, जलजन्य आय','ज्ञानी सल्लाहकार, उदार, गहिरो स्नेह र ममता','गुरुः कर्के शत्रुस्थो दुःखकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 11','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,5,'गुरु सामान्य अवस्थामा मध्यम फल दिन्छ। सिंह राशिको राजसी र आत्मविश्वासी स्वभाव र गुरुको ज्ञान गुण मिसिएर फल मध्यम र सन्तुलित रहने। यसले प्रतिष्ठा र नेतृत्वमा विशेष प्रभाव देखिन्छ।',NULL,'ज्ञान, भाग्य, धर्म, दीर्घायु, नेतृत्व','अति उदारता, अति आशावाद, अहंकार, दम्भ','शिक्षण, धर्म, विधि, प्रशासन','भाग्यबाट लाभ, उदार खर्चसँगै प्रतिष्ठाजनक आय','ज्ञानी सल्लाहकार, उदार, आदर चाहने','गुरुः सिंहे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 11','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,6,'गुरु नीच अवस्थामा कमजोर भई फलमा बाधा ल्याउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभाव र गुरुको ज्ञान गुण मिसिएर फल कमजोर र बाधापूर्ण बन्ने। यसले सेवा र व्यवस्थापनमा विशेष प्रभाव देखिन्छ।',NULL,'ज्ञान, भाग्य, धर्म, दीर्घायु, विश्लेषण','अति उदारता, अति आशावाद, आलोचनात्मकता, चिन्ता','शिक्षण, धर्म, विधि, चिकित्सा','भाग्यबाट लाभ, योजनाबद्ध बचत','ज्ञानी सल्लाहकार, उदार, व्यावहारिक स्नेह','गुरुः कन्यायां नीचस्थो दुर्बलः भवति।','Brihat Parashara Hora Shastra, Adhyaya 11','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,7,'गुरु सामान्य अवस्थामा मध्यम फल दिन्छ। तुला राशिको सन्तुलित र कलात्मक स्वभाव र गुरुको ज्ञान गुण मिसिएर फल मध्यम र सन्तुलित रहने। यसले न्याय र सामञ्जस्यमा विशेष प्रभाव देखिन्छ।',NULL,'ज्ञान, भाग्य, धर्म, दीर्घायु, न्याय','अति उदारता, अति आशावाद, निर्णय ढिलाइ, अति सम्झौता','शिक्षण, धर्म, विधि, कानुन','भाग्यबाट लाभ, सन्तुलित आय','ज्ञानी सल्लाहकार, उदार, सामञ्जस्यपूर्ण जीवनसाथी','गुरुः तुलायां सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 11','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,8,'गुरु सामान्य अवस्थामा मध्यम फल दिन्छ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभाव र गुरुको ज्ञान गुण मिसिएर फल मध्यम र सन्तुलित रहने। यसले अन्तर्दृष्टि र परिवर्तनमा विशेष प्रभाव देखिन्छ।',NULL,'ज्ञान, भाग्य, धर्म, दीर्घायु, अन्तर्दृष्टि','अति उदारता, अति आशावाद, षड्यन्त्रवाद, अति गोपन','शिक्षण, धर्म, विधि, अनुसन्धान','भाग्यबाट लाभ, अचानक उतारचढाव','ज्ञानी सल्लाहकार, उदार, गहिरो तर तीव्र','गुरुः वृश्चिके सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 11','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,10,'गुरु सामान्य अवस्थामा मध्यम फल दिन्छ। मकर राशिको अनुशासित र धैर्यवान स्वभाव र गुरुको ज्ञान गुण मिसिएर फल मध्यम र सन्तुलित रहने। यसले कर्म र उन्नतिमा विशेष प्रभाव देखिन्छ।',NULL,'ज्ञान, भाग्य, धर्म, दीर्घायु, कर्मठता','अति उदारता, अति आशावाद, निराशावाद, कठोरता','शिक्षण, धर्म, विधि, प्रशासन','भाग्यबाट लाभ, हौले हौले सम्पत्ति','ज्ञानी सल्लाहकार, उदार, जिम्मेवार तर शब्द कम','गुरुः मकरे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 11','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,11,'गुरु सामान्य अवस्थामा मध्यम फल दिन्छ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभाव र गुरुको ज्ञान गुण मिसिएर फल मध्यम र सन्तुलित रहने। यसले नवप्रवर्तन र मित्रतामा विशेष प्रभाव देखिन्छ।',NULL,'ज्ञान, भाग्य, धर्म, दीर्घायु, नवप्रवर्तन','अति उदारता, अति आशावाद, विद्रोहीपन, भावनात्मक टाढा','शिक्षण, धर्म, विधि, प्रविधि','भाग्यबाट लाभ, नवीन तर अनियमित स्रोत','ज्ञानी सल्लाहकार, उदार, मित्रतामा आधारित','गुरुः कुम्भे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 11','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(6,1,'शुक्र शत्रु राशिमा अवरोध र कष्ट दिन्छ। मेष राशिको साहसी र ऊर्जावान स्वभाव र शुक्रको कला र सौन्दर्य मिसिएर चुनौती र अवरोध आउँदै अनुभव हुने। यसले नेतृत्व र पहलकदमीमा विशेष प्रभाव देखिन्छ।',NULL,'सौन्दर्य, कला, वैवाहिक सुख, साहस, नेतृत्व','सान्द्रता, अति भोग, जल्दबाजी, क्रोध','कला, डिजाइन, मनोरञ्जन, सेना','भौतिक सुख र धन, आत्मप्रयासबाट आय','प्रेमपूर्ण सम्बन्ध, ऊर्जावान तर धैर्य कम','शुक्रः मेषे शत्रुस्थो दुःखकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 13','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,2,'शुक्र स्वकीय राशिमा रहँदा बलियो र आत्मविश्वासी हुन्छ। वृषभ राशिको स्थिर र व्यावहारिक स्वभाव र शुक्रको कला र सौन्दर्य मिसिएर फल सुदृढ र टिकाउ बन्ने। यसले संचय र स्थिरतामा विशेष प्रभाव देखिन्छ।',NULL,'सौन्दर्य, कला, वैवाहिक सुख, धैर्य, संचय','सान्द्रता, अति भोग, जिद, अति संग्रह','कला, डिजाइन, मनोरञ्जन, कृषि','भौतिक सुख र धन, बचत र भूमि लाभ','प्रेमपूर्ण सम्बन्ध, वफादार र शान्त','शुक्रः वृषभे स्वगृहस्थो शुभो भवति।','Brihat Parashara Hora Shastra, Adhyaya 13','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,3,'शुक्र सामान्य अवस्थामा मध्यम फल दिन्छ। मिथुन राशिको चञ्चल र सञ्चारी स्वभाव र शुक्रको कला र सौन्दर्य मिसिएर फल मध्यम र सन्तुलित रहने। यसले वाणी र सम्बन्धमा विशेष प्रभाव देखिन्छ।',NULL,'सौन्दर्य, कला, वैवाहिक सुख, वाणी, बुद्धि','सान्द्रता, अति भोग, द्विधा, अस्थिरता','कला, डिजाइन, मनोरञ्जन, लेखन','भौतिक सुख र धन, बहुआय, अनियमित','प्रेमपूर्ण सम्बन्ध, मैत्रीपूर्ण तर भावना चञ्चल','शुक्रः मिथुने सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 13','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,4,'शुक्र मित्र राशिमा सहज र शुभ फल दिन्छ। कर्क राशिको भावनात्मक र पोषक स्वभाव र शुक्रको कला र सौन्दर्य मिसिएर जीवनमा सहजता र वृद्धि हुने। यसले परिवार र सुरक्षामा विशेष प्रभाव देखिन्छ।',NULL,'सौन्दर्य, कला, वैवाहिक सुख, करुणा, स्मृति','सान्द्रता, अति भोग, मनोद्वन्द्व, कुढ्ने स्वभाव','कला, डिजाइन, मनोरञ्जन, खाद्य','भौतिक सुख र धन, चल सम्पत्ति, जलजन्य आय','प्रेमपूर्ण सम्बन्ध, गहिरो स्नेह र ममता','शुक्रः कर्के मित्रस्थो हितकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 13','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,5,'शुक्र सामान्य अवस्थामा मध्यम फल दिन्छ। सिंह राशिको राजसी र आत्मविश्वासी स्वभाव र शुक्रको कला र सौन्दर्य मिसिएर फल मध्यम र सन्तुलित रहने। यसले प्रतिष्ठा र नेतृत्वमा विशेष प्रभाव देखिन्छ।',NULL,'सौन्दर्य, कला, वैवाहिक सुख, नेतृत्व, दानशीलता','सान्द्रता, अति भोग, अहंकार, दम्भ','कला, डिजाइन, मनोरञ्जन, प्रशासन','भौतिक सुख र धन, उदार खर्चसँगै प्रतिष्ठाजनक आय','प्रेमपूर्ण सम्बन्ध, आदर चाहने, उदार','शुक्रः सिंहे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 13','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,6,'शुक्र नीच अवस्थामा कमजोर भई फलमा बाधा ल्याउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभाव र शुक्रको कला र सौन्दर्य मिसिएर फल कमजोर र बाधापूर्ण बन्ने। यसले सेवा र व्यवस्थापनमा विशेष प्रभाव देखिन्छ।',NULL,'सौन्दर्य, कला, वैवाहिक सुख, विश्लेषण, शुद्धता','सान्द्रता, अति भोग, आलोचनात्मकता, चिन्ता','कला, डिजाइन, मनोरञ्जन, चिकित्सा','भौतिक सुख र धन, योजनाबद्ध बचत','प्रेमपूर्ण सम्बन्ध, व्यावहारिक स्नेह, सेवा','शुक्रः कन्यायां नीचस्थो दुर्बलः भवति।','Brihat Parashara Hora Shastra, Adhyaya 13','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,8,'शुक्र सामान्य अवस्थामा मध्यम फल दिन्छ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभाव र शुक्रको कला र सौन्दर्य मिसिएर फल मध्यम र सन्तुलित रहने। यसले अन्तर्दृष्टि र परिवर्तनमा विशेष प्रभाव देखिन्छ।',NULL,'सौन्दर्य, कला, वैवाहिक सुख, अन्तर्दृष्टि, परिवर्तन','सान्द्रता, अति भोग, षड्यन्त्रवाद, अति गोपन','कला, डिजाइन, मनोरञ्जन, अनुसन्धान','भौतिक सुख र धन, अचानक उतारचढाव','प्रेमपूर्ण सम्बन्ध, गहिरो तर तीव्र','शुक्रः वृश्चिके सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 13','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,9,'शुक्र सामान्य अवस्थामा मध्यम फल दिन्छ। धनु राशिको धार्मिक र जिज्ञासु स्वभाव र शुक्रको कला र सौन्दर्य मिसिएर फल मध्यम र सन्तुलित रहने। यसले ज्ञान र यात्रामा विशेष प्रभाव देखिन्छ।',NULL,'सौन्दर्य, कला, वैवाहिक सुख, ज्ञान, आशावाद','सान्द्रता, अति भोग, अति विश्वास, उद्देश्य भ्रम','कला, डिजाइन, मनोरञ्जन, शिक्षण','भौतिक सुख र धन, भाग्यबाट लाभ, उदार खर्च','प्रेमपूर्ण सम्बन्ध, स्वतन्त्रता दिने','शुक्रः धनौ सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 13','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,10,'शुक्र सामान्य अवस्थामा मध्यम फल दिन्छ। मकर राशिको अनुशासित र धैर्यवान स्वभाव र शुक्रको कला र सौन्दर्य मिसिएर फल मध्यम र सन्तुलित रहने। यसले कर्म र उन्नतिमा विशेष प्रभाव देखिन्छ।',NULL,'सौन्दर्य, कला, वैवाहिक सुख, कर्मठता, धैर्य','सान्द्रता, अति भोग, निराशावाद, कठोरता','कला, डिजाइन, मनोरञ्जन, प्रशासन','भौतिक सुख र धन, हौले हौले सम्पत्ति','प्रेमपूर्ण सम्बन्ध, जिम्मेवार तर शब्द कम','शुक्रः मकरे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 13','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,11,'शुक्र सामान्य अवस्थामा मध्यम फल दिन्छ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभाव र शुक्रको कला र सौन्दर्य मिसिएर फल मध्यम र सन्तुलित रहने। यसले नवप्रवर्तन र मित्रतामा विशेष प्रभाव देखिन्छ।',NULL,'सौन्दर्य, कला, वैवाहिक सुख, नवप्रवर्तन, मित्रता','सान्द्रता, अति भोग, विद्रोहीपन, भावनात्मक टाढा','कला, डिजाइन, मनोरञ्जन, प्रविधि','भौतिक सुख र धन, नवीन तर अनियमित स्रोत','प्रेमपूर्ण सम्बन्ध, मित्रतामा आधारित','शुक्रः कुम्भे सामान्यफलो भवति।','Brihat Parashara Hora Shastra, Adhyaya 13','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,12,'शुक्र मीन राशिमा उच्चस्थ भई चरम बल पाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभाव र शुक्रको कला र सौन्दर्य मिसिएर संयोजन उत्कृष्ट र उज्ज्वल फल दिने। यसले करुणा र कल्पनामा विशेष प्रभाव देखिन्छ।',NULL,'सौन्दर्य, कला, वैवाहिक सुख, कल्पनाशक्ति, करुणा','सान्द्रता, अति भोग, अस्पष्टता, भाग्यमा अति निर्भरता','कला, डिजाइन, मनोरञ्जन, सेवा','भौतिक सुख र धन, स्रोत अनिश्चित, दानशीलता','प्रेमपूर्ण सम्बन्ध, निःशर्त प्रेम, बलिदान','शुक्रः मीने उच्चस्थो बलवान् भवति।','Brihat Parashara Hora Shastra, Adhyaya 13','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(7,1,'शनि नीच अवस्थामा कमजोर भई फलमा बाधा ल्याउँछ। मेष राशिको साहसी र ऊर्जावान स्वभाव र शनिको कर्म परिश्रम मिसिएर फल कमजोर र बाधापूर्ण बन्ने। यसले नेतृत्व र पहलकदमीमा विशेष प्रभाव देखिन्छ।',NULL,'अनुशासन, धैर्य, दिगो उन्नति, साहस, नेतृत्व','ढिलाइ, निराशावाद, कठोरता, जल्दबाजी','प्रशासन, श्रम, यन्त्र उद्योग, सेना','हौले जमेको सम्पत्ति, आत्मप्रयासबाट आय','जिम्मेवार तर शब्द कम, ऊर्जावान तर धैर्य कम','शनिः मेषे नीचस्थो दुर्बलः भवति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार तिल तेल दान गर्ने।'),
(7,2,'शनि शत्रु राशिमा अवरोध र कष्ट दिन्छ। वृषभ राशिको स्थिर र व्यावहारिक स्वभाव र शनिको कर्म परिश्रम मिसिएर चुनौती र अवरोध आउँदै अनुभव हुने। यसले संचय र स्थिरतामा विशेष प्रभाव देखिन्छ।',NULL,'अनुशासन, धैर्य, दिगो उन्नति, संचय, व्यावहारिकता','ढिलाइ, निराशावाद, कठोरता, जिद','प्रशासन, श्रम, यन्त्र उद्योग, कृषि','हौले जमेको सम्पत्ति, बचत र भूमि लाभ','जिम्मेवार तर शब्द कम, वफादार र शान्त','शनिः वृषभे शत्रुस्थो दुःखकृत् भवति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार तिल तेल दान गर्ने।'),
